cardCss:
/* Tarjeta: papel claro o noche cálida (como el cuaderno web), una cabecera con tipo y nivel, la respuesta en su
   bloque y las notas en secciones. CSS sencillo, sin color-mix ni trucos: AnkiDroid, AnkiMobile y escritorio. */
.card { font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 20px; line-height: 1.4;
        text-align: center; color: #1f1a16; background: #faf7ef; padding: 10px 8px 28px;
        --muted: rgba(31,26,22,.55); --line: rgba(31,26,22,.13); --panel: rgba(31,26,22,.045); --lv: #b3301d; }
.nightMode.card, .night_mode .card, .card.nightMode { color: #ececec; background: #1b1b1b;
        --muted: rgba(236,236,236,.55); --line: rgba(236,236,236,.13); --panel: rgba(255,255,255,.045); }
.meta { display: flex; justify-content: space-between; align-items: center; max-width: 30em; margin: 0 auto 14px;
        padding-top: 7px; border-top: 3px solid var(--lv); font: 700 11px/1 Menlo, Consolas, monospace;
        letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }
.lv-1 { --lv: #b3301d; } .lv-2 { --lv: #d0632f; } .lv-3 { --lv: #df9340; } .lv-4 { --lv: #cdb35c; }
.lv-5 { --lv: #8fa972; } .lv-6 { --lv: #5f9590; } .lv-7 { --lv: #557aa3; }
.task { font-size: 17px; line-height: 1.45; max-width: 26em; margin: 0 auto 14px; color: var(--muted); text-align: left; }
.task .meta { font-size: 11px; }
.meta .code { letter-spacing: .06em; text-transform: none; opacity: .8; }
.front { margin: 6px 0; }
.hanzi { font-size: 54px; line-height: 1.2; }
.said { display: flex; align-items: center; justify-content: center; gap: 10px; margin: 8px 0; }
.said .who { font-size: 30px; }
.said .bubble { border: 2px solid var(--line); border-radius: 16px; padding: 6px 14px; }
.said .bubble .hanzi { font-size: 40px; }
.said .bubble .pinyin { font-size: 20px; }
.said.you .dots { font-size: 34px; letter-spacing: 4px; color: var(--muted); }
.said-tr { margin-top: 8px; color: var(--muted); }
.stack .slash { font-size: 30px; line-height: 1; color: var(--muted); margin: 2px 0; }
.stack .hanzi.small { font-size: 40px; }
.pinyin { font-size: 24px; margin-top: 4px; }
.meaning { font-size: 20px; margin-top: 10px; }
.ipa { font-size: 15px; color: var(--muted); margin-top: 2px; }
.legend { font-size: 13px; color: var(--muted); margin-top: 10px; }
.pos { font-style: italic; }
hr#answer { border: 0; border-top: 1px solid var(--line); max-width: 30em; margin: 20px auto 16px; }
.answer { max-width: 30em; margin: 0 auto; padding: 14px 12px 16px; border-radius: 16px; background: var(--panel);
          border: 1px solid var(--line); }
.box { max-width: 30em; margin: 14px auto 0; text-align: left; font-size: 15px; line-height: 1.55; }
.note { margin-top: 10px; padding: 10px 12px 11px; border-radius: 12px; border: 1px solid var(--line); background: var(--panel); }
.note h4 { margin: 0 0 6px; font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--muted); }
.note--group .note-body > div { padding: 5px 8px; margin: 0 -8px; border-radius: 8px; }
.note--group .note-body > div + div { border-top: 1px solid var(--line); }
.note--group .is-target { background: rgba(179,48,29,.13); }
.vs-row { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; }
.vs-hz { font-size: 24px; font-weight: 400; min-width: 1.6em; }
.vs-py { font-size: 15px; }
.vs-gl { font-size: 15px; }
.vs-cue { flex-basis: 100%; font-size: 13px; font-style: italic; color: var(--muted); }
.vs-ex { flex-basis: 100%; margin-top: 4px; }
.is-target .vs-hz { font-weight: 700; }
.note--chars .ch-row { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; padding: 4px 0; }
.note--chars .ch-row + .ch-row { border-top: 1px solid var(--line); }
.ch-hz { font-size: 26px; font-weight: 400; min-width: 1.3em; }
.ch-py { font-size: 15px; color: var(--muted); }
.pair-n { font-weight: 600; margin: 0 4px 0 10px; color: var(--muted); }
.pair-row { display: flex; align-items: baseline; gap: 10px; justify-content: center; padding: 4px 0; }
.ch-gl { font-size: 15px; }
.ch-kind { font-size: 12px; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); }
.ch-formula { font-size: 14px; color: #1f5f8a; }
.nightMode .ch-formula, .night_mode .ch-formula { color: #8cc0e6; }
.ch-why { flex-basis: 100%; font-size: 14px; color: var(--muted); }
.ch-memory { flex-basis: 100%; font-size: 14px; font-style: italic; color: var(--muted); }
.ch-also { flex-basis: 100%; font-size: 13px; color: var(--muted); }
.note--example { text-align: center; }
.note--mnemonic { border: 1px dashed #c98a12; background: rgba(233,168,40,.10); }
.timeline { margin: 8px 0 2px; }
.tl-row { position: relative; height: 42px; }
.tl-bar { position: absolute; top: 2px; height: 18px; line-height: 18px; border-radius: 9px; font-size: 13px; text-align: center; background: rgba(127,127,127,.18); white-space: nowrap; overflow: hidden; }
.tl-bar.is-target { background: rgba(179,48,29,.25); font-weight: bold; }
.tl-label { position: absolute; top: 21px; white-space: nowrap; font-size: 13px; }
.tl-row.is-target .tl-label { font-weight: 700; }
/* Diagramas (review 013): nombre de cada elemento debajo de su marca, hanzi y pinyin con el color de su tono. */
.dg-hz { font-size: 16px; } .dg-py { font-size: 13px; } .dg-note { font-size: 12px; color: var(--muted); }
.scale { position: relative; height: 92px; margin: 10px 26px 4px; }
.sc-axis { position: absolute; left: 0; right: 0; top: 10px; border-top: 2px solid var(--line); }
.sc-axis::after { content: "▶"; position: absolute; right: -14px; top: -10px; font-size: 13px; color: var(--muted); }
.sc-pt { position: absolute; top: 4px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center;
         text-align: center; width: 5.2em; line-height: 1.25; }
.sc-dot { width: 12px; height: 12px; border-radius: 50%; background: rgba(127,127,127,.45); margin-bottom: 4px; }
.sc-pt.is-target .sc-dot { background: #b3301d; } .sc-pt.is-target .dg-hz { font-weight: 700; }
.aspect { margin: 10px 0 2px; }
.as-row { position: relative; height: 16px; }
.as-now { position: absolute; left: 50%; top: -2px; bottom: -2px; border-left: 2px dashed rgba(179,48,29,.55); }
.as-bar { position: absolute; top: 4px; height: 8px; border-radius: 4px; background: rgba(127,127,127,.35); }
.as-dot { position: absolute; top: 2px; width: 12px; height: 12px; margin-left: -6px; border-radius: 50%; background: rgba(127,127,127,.5); }
.as-bar.is-target, .as-dot.is-target { background: #b3301d; }
.as-label { font-size: 13px; margin: 0 0 6px; } .as-label.is-target .dg-hz { font-weight: 700; }
.as-ticks { position: relative; height: 16px; font-size: 11px; color: var(--muted); border-top: 1px solid var(--line); margin-top: 2px; }
.as-ticks span { position: absolute; transform: translateX(-50%); } .as-ticks span:first-child { transform: none; }
.as-ticks span:last-child { transform: translateX(-100%); }
.tl-ticks { position: relative; height: 14px; font-size: 10px; opacity: .7; }
.tl-ticks span { position: absolute; transform: translateX(-50%); }
.nuance-words { margin-top: 10px; text-align: left; }
.nuance-words .vs-row { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: baseline; padding: 4px 0; }
.nuance-words .vs-row + .vs-row { border-top: 1px solid var(--line); }
.note-body p { margin: 0; }
.note-body p + p { margin-top: 6px; }
.note--mnemonic h4::before { content: "🧠 "; }
.note--usage { border-left: 4px solid #6a5acd; background: rgba(106,90,205,.08); }
.note--usage h4::before { content: "🗣️ "; }
.note--connection { border-left: 4px solid #2a9d8f; background: rgba(42,157,143,.09); }
.note--teacher { border-left: 3px solid var(--lv); }
/* Uso y significado, con aspecto de nota: papel claro, borde de color e icono (review 013). El apunte, más discreto. */
.note--linguistic { border-left: 4px solid #b8892b; background: rgba(250,236,190,.40); }
.nightMode .note--linguistic, .night_mode .note--linguistic { background: rgba(184,137,43,.13); }
.note--linguistic h4::before { content: "📝 "; }
.note--note { border-style: dotted; }
.note--note h4::before { content: "✎ "; }
/* Otras formas de decirlo y las familias (series, patrones, diagramas): otro aspecto, más abajo; lo que solo se
   parece a la vista o al oído, lo último y más apagado (review 013). */
.note--alts { border-left: 4px solid #2f7d6d; background: rgba(47,125,109,.08); }
.note--alts h4::before { content: "🔁 "; }
.note--alts .example { text-align: center; }
.note--family { border-left: 4px solid #4e79a7; background: rgba(78,121,167,.07); }
.note--family h4::before { content: "🧭 "; }
.note--family .vs-row, .note--confusable .vs-row { padding: 5px 8px; margin: 0 -8px; border-radius: 8px; }
.note--family .vs-row + .vs-row, .note--confusable .vs-row + .vs-row { border-top: 1px solid var(--line); }
.note--family .is-target.vs-row, .note--confusable .is-target.vs-row { background: rgba(179,48,29,.13); }
.note--confusable { opacity: .92; border-style: dashed; }
.note--confusable h4::before { content: "👀 "; }
.example + .example { margin-top: 14px; }
.option { margin: 10px 0; }
.option .hanzi.small, .hanzi.small { font-size: 32px; }
.wrong { margin: 12px 0; color: var(--muted); }
.wrong .hz { text-decoration: line-through; font-size: 22px; }
.sent { display: inline-flex; gap: 4px; align-items: flex-end; flex-wrap: wrap; justify-content: center; }
.seg { display: inline-flex; flex-direction: column; align-items: center; padding: 0 2px;
       border-bottom: 3px solid var(--c, transparent); }
.seg .py { font-size: 15px; }
.seg .hz { font-size: 30px; }
.box .seg .hz { font-size: 24px; }
.gap { min-width: 1.6em; border-bottom: 3px dashed #999; }
/* Alinear hanzi y pinyin: un subrayado gris, alterno entre palabras; el color es del tono. */
.c0, .c2, .c4 { --c: rgba(31,26,22,.32); } .c1, .c3 { --c: rgba(31,26,22,.12); }
.nightMode .c0, .nightMode .c2, .nightMode .c4, .night_mode .c0, .night_mode .c2, .night_mode .c4 { --c: rgba(236,236,236,.36); }
.nightMode .c1, .nightMode .c3, .night_mode .c1, .night_mode .c3 { --c: rgba(236,236,236,.14); }
/* Colores por tono (TONE_CLASS): 1 rojo, 2 verde, 3 azul, 4 morado; el neutro, del color del texto (blanco de
   noche, negro de día: YAGO, 2026-10-16). */
.t1 { color: #d1342b; } .t2 { color: #23893a; } .t3 { color: #2563c9; } .t4 { color: #8a3fb0; } .t5 { color: inherit; }
.nightMode .t1, .night_mode .t1 { color: #ff7e72; } .nightMode .t2, .night_mode .t2 { color: #6fd07f; }
.nightMode .t3, .night_mode .t3 { color: #82acff; } .nightMode .t4, .night_mode .t4 { color: #cf95f2; }
.acs-in { font-size: 20px; padding: 10px 14px; width: 12em; max-width: 90%; margin-top: 14px; text-align: center;
          border: 1px solid var(--line); border-radius: 12px; background: var(--panel); color: inherit; outline: none; }
#acs-result { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
.acs-ok { color: #2e7d32; } .acs-bad { color: #c62828; }
.nightMode .acs-ok, .night_mode .acs-ok { color: #7cc36f; } .nightMode .acs-bad, .night_mode .acs-bad { color: #e8845a; }
.pattern { align-items: flex-end; gap: 6px; }
.pattern .plus { align-self: center; color: var(--muted); font-size: 18px; }
.slot { display: inline-flex; flex-direction: column; align-items: center; padding: 2px 8px 4px; border-radius: 8px;
        border: 2px dashed var(--s); }
.slot .hz { font-size: 16px; font-style: italic; color: var(--s); }
.slot-S { --s: #4e79a7; } .slot-N { --s: #59a14f; } .slot-V { --s: #e15759; } .slot-Adj { --s: #f28e2b; }
.slot-Num { --s: #b07aa1; } .slot-Nombre { --s: #76b7b2; } .slot-Lugar { --s: #9c755f; }
.slot-Tiempo { --s: #edc948; } .slot-Frase { --s: #8c8c8c; }
.passage { max-width: 26em; margin: 0 auto; text-align: left; }
.choices { max-width: 26em; margin: 12px auto 0; padding: 0; list-style: none; text-align: left; }
.choices li { font-size: 24px; padding: 4px 0; }
.choices .opt, .choice-ok { font: 700 15px/1 Menlo, Consolas, monospace; color: var(--muted); margin-right: 6px; }
.choice-ok { font-size: 20px; color: inherit; margin: 0 0 10px; }
.words { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; max-width: 26em; margin: 8px auto 0; }
.word { display: inline-flex; flex-direction: column; align-items: center; padding: 6px 10px; border-radius: 10px;
        border: 1px solid var(--line); background: var(--panel); }
.word .hz { font-size: 28px; } .word .py { font-size: 14px; color: var(--muted); }
.passage .hz-line { font-size: 28px; line-height: 1.6; }
.passage .sent { justify-content: flex-start; margin: 0 6px 6px 0; }
details.question { max-width: 26em; margin: 18px auto 0; padding: 10px 12px; border-radius: 12px;
                   border: 1px solid var(--line); background: var(--panel); }
details.question summary { font: 700 12px/1.4 Menlo, Consolas, monospace; letter-spacing: .1em;
                           text-transform: uppercase; color: var(--muted); cursor: pointer; }
details.question .hz-line { font-size: 24px; margin-top: 8px; }
